    return ['Content-Type: application/json','X-Baiamonte-Key-Id: baiamonte-intake-1','X-Baiamonte-Timestamp: '.(string)$timestamp,'X-Baiamonte-Nonce: '.$nonce,'X-Baiamonte-Signature: sha256='.hash_hmac('sha256',$canonical,$key)];
}
